package com.trainflow.pricing; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes;
@Entity @Table(name="training_pricings") public class TrainingPricing{@Id@JdbcTypeCode(SqlTypes.VARCHAR)@Column(columnDefinition="char(36)")private UUID id;@JdbcTypeCode(SqlTypes.VARCHAR)@Column(name="training_case_id",nullable=false,unique=true,columnDefinition="char(36)")private UUID trainingCaseId;@Column(nullable=false,length=3)private String currency="TND";@Column(name="trainer_cost",precision=15,scale=3,nullable=false)private BigDecimal trainerCost=BigDecimal.ZERO;@Column(name="transport_cost",precision=15,scale=3,nullable=false)private BigDecimal transportCost=BigDecimal.ZERO;@Column(name="room_cost",precision=15,scale=3,nullable=false)private BigDecimal roomCost=BigDecimal.ZERO;@Column(name="meal_cost",precision=15,scale=3,nullable=false)private BigDecimal mealCost=BigDecimal.ZERO;@Column(name="other_cost",precision=15,scale=3,nullable=false)private BigDecimal otherCost=BigDecimal.ZERO;@Column(name="margin_rate",precision=6,scale=3,nullable=false)private BigDecimal marginRate=BigDecimal.ZERO;@Column(name="vat_rate",precision=6,scale=3,nullable=false)private BigDecimal vatRate=new BigDecimal("19");@Column(name="vat_exemption_reason",columnDefinition="text")private String vatExemptionReason;@Column(name="vat_legal_reference",length=500)private String vatLegalReference;@Column(name="trainer_daily_rate_snapshot",precision=15,scale=3)private BigDecimal trainerDailyRateSnapshot;@Column(name="trainer_hourly_rate_snapshot",precision=15,scale=3)private BigDecimal trainerHourlyRateSnapshot;@Column(name="program_day_count_snapshot",nullable=false)private int programDayCountSnapshot;@Column(name="program_duration_minutes_snapshot",nullable=false)private int programDurationMinutesSnapshot;@Enumerated(EnumType.STRING)@Column(name="trainer_cost_initialization_method",nullable=false,length=20)private TrainerCostInitializationMethod initializationMethod;@Column(name="is_submitted",nullable=false)private boolean submitted;@Column(name="submitted_at")private Instant submittedAt;@Column(name="is_validated",nullable=false)private boolean validated;@Column(name="validated_at")private Instant validatedAt;@Column(name="returned_at")private Instant returnedAt;@Column(name="return_reason",columnDefinition="text")private String returnReason;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;protected TrainingPricing(){}public TrainingPricing(UUID c){id=UUID.randomUUID();trainingCaseId=c;}@PrePersist void insert(){var n=Instant.now();if(id==null)id=UUID.randomUUID();if(createdAt==null)createdAt=n;updatedAt=n;}@PreUpdate void update(){updatedAt=Instant.now();}public UUID getId(){return id;}public UUID getTrainingCaseId(){return trainingCaseId;}public String getCurrency(){return currency;}public BigDecimal getTrainerCost(){return trainerCost;}public void setTrainerCost(BigDecimal v){trainerCost=v;}public BigDecimal getTransportCost(){return transportCost;}public void setTransportCost(BigDecimal v){transportCost=v;}public BigDecimal getRoomCost(){return roomCost;}public void setRoomCost(BigDecimal v){roomCost=v;}public BigDecimal getMealCost(){return mealCost;}public void setMealCost(BigDecimal v){mealCost=v;}public BigDecimal getOtherCost(){return otherCost;}public void setOtherCost(BigDecimal v){otherCost=v;}public BigDecimal getMarginRate(){return marginRate;}public void setMarginRate(BigDecimal v){marginRate=v;}public BigDecimal getVatRate(){return vatRate;}public void setVatRate(BigDecimal v){vatRate=v;}public String getVatExemptionReason(){return vatExemptionReason;}public void setVatExemptionReason(String v){vatExemptionReason=v;}public String getVatLegalReference(){return vatLegalReference;}public void setVatLegalReference(String v){vatLegalReference=v;}public BigDecimal getTrainerDailyRateSnapshot(){return trainerDailyRateSnapshot;}public void setTrainerDailyRateSnapshot(BigDecimal v){trainerDailyRateSnapshot=v;}public BigDecimal getTrainerHourlyRateSnapshot(){return trainerHourlyRateSnapshot;}public void setTrainerHourlyRateSnapshot(BigDecimal v){trainerHourlyRateSnapshot=v;}public int getProgramDayCountSnapshot(){return programDayCountSnapshot;}public void setProgramDayCountSnapshot(int v){programDayCountSnapshot=v;}public int getProgramDurationMinutesSnapshot(){return programDurationMinutesSnapshot;}public void setProgramDurationMinutesSnapshot(int v){programDurationMinutesSnapshot=v;}public TrainerCostInitializationMethod getInitializationMethod(){return initializationMethod;}public void setInitializationMethod(TrainerCostInitializationMethod v){initializationMethod=v;}public boolean isSubmitted(){return submitted;}public void setSubmitted(boolean v){submitted=v;}public Instant getSubmittedAt(){return submittedAt;}public void setSubmittedAt(Instant v){submittedAt=v;}public boolean isValidated(){return validated;}public void setValidated(boolean v){validated=v;}public Instant getValidatedAt(){return validatedAt;}public void setValidatedAt(Instant v){validatedAt=v;}public Instant getReturnedAt(){return returnedAt;}public void setReturnedAt(Instant v){returnedAt=v;}public String getReturnReason(){return returnReason;}public void setReturnReason(String v){returnReason=v;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}}
